.github/workflows/release.yml:15:    steps:
.github/workflows/release.yml:16:      - id: verify
.github/workflows/release.yml:17:        name: Verify annotated GitHub-signed tag without repository checkout
.github/workflows/release.yml:18:        env:
.github/workflows/release.yml:19:          GH_TOKEN: ${{ github.token }}
.github/workflows/release.yml:20:          TAG: ${{ github.ref_name }}
.github/workflows/release.yml:21:          REPOSITORY: ${{ github.repository }}
.github/workflows/release.yml:22:          EXPECTED: ${{ github.sha }}
.github/workflows/release.yml:23:        run: |
.github/workflows/release.yml:24:          set -euo pipefail
.github/workflows/release.yml:25:          ref=$(gh api "repos/$REPOSITORY/git/ref/tags/$TAG")
.github/workflows/release.yml:26:          test "$(jq -r '.object.type' <<<"$ref")" = tag
.github/workflows/release.yml:27:          tag=$(gh api "repos/$REPOSITORY/git/tags/$(jq -r '.object.sha' <<<"$ref")")
.github/workflows/release.yml:28:          test "$(jq -r '.verification.verified' <<<"$tag")" = true
.github/workflows/release.yml:29:          test "$(jq -r '.object.type' <<<"$tag")" = commit
.github/workflows/release.yml:30:          commit=$(jq -r '.object.sha' <<<"$tag")
.github/workflows/release.yml:31:          test "$commit" = "$EXPECTED"
.github/workflows/release.yml:32:          echo "commit=$commit" >> "$GITHUB_OUTPUT"
